<?php

declare(strict_types=1);

namespace Hypervel\Passport\Database\Factories;

use Hypervel\Database\Eloquent\Factories\Factory;
use Hypervel\Passport\Client;
use Hypervel\Passport\Passport;
use Hypervel\Support\Str;

/**
 * @extends Factory<Client>
 */
class ClientFactory extends Factory
{
    /**
     * Get the name of the model that is generated by the factory.
     *
     * @return class-string<Client>
     */
    public function modelName(): string
    {
        return $this->model ?? Passport::clientModel();
    }

    /**
     * Define the model's default state.
     *
     * @return array<string, mixed>
     */
    public function definition(): array
    {
        return [
            'owner_id' => null,
            'owner_type' => null,
            'name' => $this->faker->company(),
            'secret' => Str::random(40),
            'redirect_uris' => [$this->faker->url()],
            'grant_types' => ['authorization_code', 'refresh_token'],
            'revoked' => false,
        ];
    }

    /**
     * Use as a public client.
     */
    public function asPublic(): static
    {
        return $this->state([
            'secret' => null,
        ]);
    }

    // Password-grant clients are omitted; use authorization code with PKCE or device authorization.

    /**
     * Use as a Personal Access Token client.
     */
    public function asPersonalAccessTokenClient(): static
    {
        return $this->state([
            'grant_types' => ['personal_access'],
            'redirect_uris' => [],
        ]);
    }

    // Implicit-grant clients are omitted; use authorization code with PKCE.

    /**
     * Use as a Client Credentials client.
     */
    public function asClientCredentials(): static
    {
        return $this->state([
            'grant_types' => ['client_credentials'],
            'redirect_uris' => [],
        ]);
    }

    /**
     * Use as a Device Code client.
     */
    public function asDeviceCodeClient(): static
    {
        return $this->state([
            'grant_types' => ['urn:ietf:params:oauth:grant-type:device_code', 'refresh_token'],
            'redirect_uris' => [],
        ]);
    }
}
